mapper.select:
SELECT refund_order_id AS refundOrderId, payment_order_id AS paymentOrderId, order_no AS orderNo, customer_name AS customerName, CONCAT('¥', FORMAT(refund_amount, 2)) AS refundAmount, refund_method AS refundMethod, status, status_type AS statusType, DATE_FORMAT(applied_at, '%Y-%m-%d %H:%i:%s') AS appliedAt, CASE WHEN success_at IS NULL THEN '-' ELSE DATE_FORMAT(success_at, '%Y-%m-%d %H:%i:%s') END AS successAt FROM t_refund_order
refund_order_id LIKE CONCAT('%', #{query.refundOrderId}, '%')
AND payment_order_id LIKE CONCAT('%', #{query.paymentOrderId}, '%')
AND status = 'SUCCESS' AND success_at IS NULL
AND status IN ('REVIEWING', 'PROCESSING')
AND status = #{query.refundStatus}
AND refund_method = #{query.refundMethod}
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT refund_attempt_no
FROM t_refund_attempt
WHERE channel_code = #{channelCode}
  AND channel_refund_no = #{channelRefundNo}
LIMIT 1

mapper.update:
UPDATE t_refund_order
SET channel_code = #{channelCode},
    channel_refund_no = #{channelRefundNo},
    channel_submitted_at = NOW()
WHERE refund_order_id = #{refundOrderId}
  AND status = 'PROCESSING'
  AND channel_refund_no IS NULL
  AND EXISTS (
      SELECT 1
      FROM t_refund_attempt attempt
      WHERE attempt.refund_attempt_no = #{refundAttemptNo}
        AND attempt.refund_order_id = #{refundOrderId}
        AND attempt.channel_code = #{channelCode}
        AND attempt.channel_refund_no = #{channelRefundNo}
        AND attempt.attempt_status = 'ACCEPTED'
        AND attempt.id = (
            SELECT latest_attempt.id
            FROM t_refund_attempt latest_attempt
            WHERE latest_attempt.refund_order_id = #{refundOrderId}
            ORDER BY latest_attempt.created_at DESC, latest_attempt.id DESC
            LIMIT 1
        )
  )

UPDATE t_refund_order
SET channel_code = #{channelCode},
    channel_refund_no = #{channelRefundNo},
    channel_submitted_at = NOW()
WHERE refund_order_id = #{refundOrderId}
  AND status = 'PROCESSING'
  AND channel_refund_no IS NULL
  AND EXISTS (
      SELECT 1
      FROM t_payment_event event
      WHERE event.event_type = 'REFUND_SUBMIT'
        AND event.biz_no = #{refundAttemptNo}
        AND event.publish_status = 'UNKNOWN'
  )
  AND EXISTS (
      SELECT 1
      FROM t_refund_attempt attempt
      WHERE attempt.refund_attempt_no = #{refundAttemptNo}
        AND attempt.refund_order_id = #{refundOrderId}
        AND attempt.channel_code = #{channelCode}
        AND attempt.channel_refund_no = #{channelRefundNo}
        AND attempt.attempt_status = 'ACCEPTED'
        AND attempt.id = (
            SELECT latest_attempt.id
            FROM t_refund_attempt latest_attempt
            WHERE latest_attempt.refund_order_id = #{refundOrderId}
            ORDER BY latest_attempt.created_at DESC, latest_attempt.id DESC
            LIMIT 1
        )
  )

UPDATE t_refund_order
SET channel_code = #{channelCode}
WHERE refund_order_id = #{refundOrderId}
  AND status = 'PROCESSING'
  AND channel_refund_no IS NULL
  AND EXISTS (
      SELECT 1
      FROM t_refund_attempt attempt
      WHERE attempt.refund_attempt_no = #{refundAttemptNo}
        AND attempt.refund_order_id = #{refundOrderId}
        AND attempt.channel_code = #{channelCode}
        AND attempt.channel_refund_no IS NULL
        AND attempt.attempt_status = 'UNKNOWN'
        AND attempt.id = (
            SELECT latest_attempt.id
            FROM t_refund_attempt latest_attempt
            WHERE latest_attempt.refund_order_id = #{refundOrderId}
            ORDER BY latest_attempt.created_at DESC, latest_attempt.id DESC
            LIMIT 1
        )
  )
